<?php
require_once __DIR__ . '/includes/functions.php'; require_login(); $pdo=db();
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();try{$product=(int)($_POST['product_id']??0);$type=$_POST['type']??'';$qty=(int)($_POST['quantity']??0);$note=trim($_POST['notes']??'');if(!$product||!in_array($type,['IN','OUT'],true)||$qty<1)throw new RuntimeException('Select a product, transaction type, and quantity greater than zero.');$pdo->beginTransaction();$s=$pdo->prepare('SELECT quantity FROM products WHERE id=? FOR UPDATE');$s->execute([$product]);$current=$s->fetchColumn();if($current===false)throw new RuntimeException('Product not found.');$new=$type==='IN'?(int)$current+$qty:(int)$current-$qty;if($new<0)throw new RuntimeException('Not enough stock for this stock-out transaction.');$u=$pdo->prepare('UPDATE products SET quantity=? WHERE id=?');$u->execute([$new,$product]);$i=$pdo->prepare('INSERT INTO stock_transactions(product_id,type,quantity,notes) VALUES(?,?,?,?)');$i->execute([$product,$type,$qty,$note]);$pdo->commit();flash('Stock transaction recorded.');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();flash($e instanceof RuntimeException?$e->getMessage():'Unable to record transaction.','error');}redirect('transactions.php');}
$products=$pdo->query('SELECT id,name,sku,quantity FROM products ORDER BY name')->fetchAll();$rows=$pdo->query('SELECT t.*,p.name product_name,p.sku FROM stock_transactions t JOIN products p ON p.id=t.product_id ORDER BY t.id DESC LIMIT 100')->fetchAll();$page_title='Stock transactions';require 'includes/header.php'; ?>
<section class="panel form-panel"><div class="panel-heading"><div><h3>Record stock movement</h3><p>Stock-in increases quantity; stock-out decreases quantity.</p></div></div><form method="post" class="form-grid"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><label>Product<select name="product_id" required><option value="">Choose product</option><?php foreach($products as $p): ?><option value="<?= $p['id'] ?>"><?= e($p['name']) ?> (<?= e($p['sku']) ?> · <?= (int)$p['quantity'] ?> available)</option><?php endforeach; ?></select></label><label>Transaction type<select name="type"><option value="IN">Stock in</option><option value="OUT">Stock out</option></select></label><label>Quantity<input type="number" min="1" name="quantity" required></label><label>Notes<input name="notes" placeholder="Optional note"></label><div class="form-buttons"><button class="btn primary">Record transaction</button></div></form></section>
<section class="panel"><div class="panel-heading"><div><h3>Transaction history</h3><p>Latest 100 records</p></div></div><div class="table-wrap"><table><thead><tr><th>Date</th><th>Product</th><th>SKU</th><th>Type</th><th>Quantity</th><th>Notes</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e(date('M d, Y H:i',strtotime($r['created_at']))) ?></td><td class="strong"><?= e($r['product_name']) ?></td><td><?= e($r['sku']) ?></td><td><span class="pill <?= $r['type']==='IN'?'good':'warn' ?>"><?= e($r['type']) ?></span></td><td><?= (int)$r['quantity'] ?></td><td><?= e($r['notes']) ?></td></tr><?php endforeach; ?><?php if(!$rows): ?><tr><td colspan="6" class="empty">No transactions yet.</td></tr><?php endif; ?></tbody></table></div></section>
<?php require 'includes/footer.php'; ?>
